("<b>Sample</b><span>Pre-production set</span>", "<b>打樣</b><span>產前樣品</span>", "<b>サンプル</b><span>量産前サンプル</span>", "<b>Làm mẫu</b><span>Mẫu tiền sản xuất</span>"),
